    75  static exr_result_t
    76  Classifier_read (Classifier* out, const uint8_t** ptr, size_t* size)
    77  {
    78      const uint8_t* curin = *ptr;
    79      size_t         len   = 0;
    80      uint8_t        value;
    81      uint8_t        type;
    82
    83      if (*size <= 3) return EXR_ERR_CORRUPT_CHUNK;
    84
    85      {
    86          // maximum length of string plus one byte for terminating NULL
    87          char  suffix[128 + 1];
    88          char* mem;
    89          memset (suffix, 0, 128 + 1);
    90          for (; len < 128 + 1; ++len)
    91          {
    92              if (len > (*size - 3)) return EXR_ERR_CORRUPT_CHUNK;
    93              if (curin[len] == '\0') break;
    94              suffix[len] = (char)curin[len];
    95          }
    96          len += 1;
    97          if (len == 128 + 1) return EXR_ERR_CORRUPT_CHUNK;
    98
    99          mem = internal_exr_alloc (len);
   100          if (!mem) return EXR_ERR_OUT_OF_MEMORY;
   101
   102          memcpy (mem, suffix, len);
   103          out->_suffix       = mem;
   104          out->_stringStatic = DWA_CLASSIFIER_FALSE;
   105      }
   106
   107      if (*size < len + 2 * sizeof (uint8_t))
   108          return EXR_ERR_CORRUPT_CHUNK;
   109
   110      curin += len;
   111
   112      value = curin[0];
   113      type  = curin[1];
   114
   115      curin += 2;
   116
   117      *ptr = curin;
   118      *size -= len + 2 * sizeof (uint8_t);
   119
   120      out->_cscIdx = (int) (value >> 4) - 1;
   121      if (out->_cscIdx < -1 || out->_cscIdx >= 3)
   122          return EXR_ERR_CORRUPT_CHUNK;
   123
   124      out->_scheme = (CompressorScheme) ((value >> 2) & 3);
   125      if (out->_scheme >= NUM_COMPRESSOR_SCHEMES)
   126          return EXR_ERR_CORRUPT_CHUNK;
   127
   128      out->_caseInsensitive = (value & 1 ? DWA_CLASSIFIER_TRUE : DWA_CLASSIFIER_FALSE);
   129
   130      if (type >= EXR_PIXEL_LAST_TYPE)
   131          return EXR_ERR_CORRUPT_CHUNK;
   132
   133      out->_type = (exr_pixel_type_t) type;
   134      return EXR_ERR_SUCCESS;
   135  }
