   137  static inline int
   138  Classifier_match (
   139      const Classifier* me, const char* suffix, const exr_pixel_type_t type)
   140  {
   141      if (me->_type != type) return DWA_CLASSIFIER_FALSE;
   142  #ifdef _MSC_VER
   143      if (me->_caseInsensitive) return _stricmp (suffix, me->_suffix) == 0;
   144  #else
   145      if (me->_caseInsensitive) return strcasecmp (suffix, me->_suffix) == 0;
   146  #endif
   147
   148      return strcmp (suffix, me->_suffix) == 0;
   149  }
