   151  static inline uint64_t
   152  Classifier_size (const Classifier* me)
   153  {
   154      return strlen (me->_suffix) + 1 + 2 * sizeof (uint8_t);
   155  }
   156
   157  static inline uint64_t
   158  Classifier_write (const Classifier* me, uint8_t** ptr)
   159  {
   160      uint8_t* outptr    = *ptr;
   161      uint8_t  value     = 0;
   162      uint64_t sizeBytes = strlen (me->_suffix) + 1;
   163
   164      memcpy (outptr, me->_suffix, sizeBytes);
   165      outptr += sizeBytes;
   166
   167      value |= ((uint8_t) (me->_cscIdx + 1) & 15) << 4;
   168      value |= ((uint8_t) me->_scheme & 3) << 2;
   169      value |= (uint8_t) me->_caseInsensitive & 1;
   170
   171      outptr[0] = value;
   172      outptr[1] = (uint8_t) me->_type;
   173      outptr += 2;
   174      *ptr = outptr;
   175      return sizeBytes + 2;
   176  }
